import { useCallback, useState, type KeyboardEvent } from 'react';

interface TagInputProps {
  initialTags?: string[];
  placeholder?: string;
  onChange?: (tags: string[]) => void;
}

function normalizeTag(raw: string): string {
  return raw.trim().replace(/,+$/, '');
}

export default function ArticleTagInput({
  initialTags = [],
  placeholder = 'Добавить тег и нажать Enter',
  onChange,
}: TagInputProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commitTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange]
  );

  const addTag = useCallback(
    (raw: string) => {
      const value = normalizeTag(raw);
      if (!value) return;
      if (tags.includes(value)) {
        setDraft('');
        return;
      }
      commitTags([...tags, value]);
      setDraft('');
    },
    [tags, commitTags]
  );

  const removeTag = useCallback(
    (value: string) => {
      commitTags(tags.filter((tag) => tag !== value));
    },
    [tags, commitTags]
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault();
        addTag(draft);
        return;
      }
      if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
        event.preventDefault();
        removeTag(tags[tags.length - 1]);
      }
    },
    [draft, tags, addTag, removeTag]
  );

  const handleBlur = useCallback(() => {
    if (draft.trim()) {
      addTag(draft);
    }
  }, [draft, addTag]);

  return (
    <div className="jx-field" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
      <label className="jx-label" htmlFor="article-tag-input">
        Теги статьи
      </label>
      <input
        id="article-tag-input"
        className="jx-input"
        type="text"
        value={draft}
        placeholder={placeholder}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        aria-describedby="article-tag-list"
      />
      <ul
        id="article-tag-list"
        className="jx-tag-list"
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-space-2)',
          listStyle: 'none',
          padding: 0,
          margin: 0,
        }}
      >
        {tags.length === 0 && (
          <li className="jx-tag-list__empty" aria-hidden="true">
            Пока нет тегов
          </li>
        )}
        {tags.map((tag) => (
          <li key={tag} className="jx-tag">
            <span className="jx-tag__label">{tag}</span>
            <button
              type="button"
              className="jx-tag__remove"
              aria-label={`Удалить тег ${tag}`}
              onClick={() => removeTag(tag)}
            >
              ×
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

